SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_dmht_incidence(
 id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
  result1 int(9) DEFAULT 0, 
  result2 int(9) DEFAULT 0, 
PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_dmht_incidence WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_dmht_incidence
(
SELECT
@id,p.check_hosp,p.check_vhid
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543
,COUNT(DISTINCT IF(min_date_dx_ht BETWEEN @start_d AND @end_d  AND type_dx IN(1,3),t.cid,NULL)) result1
,COUNT(DISTINCT IF(min_date_dx_dm BETWEEN @start_d AND @end_d  AND type_dx IN(2,3),t.cid,NULL)) result2
FROM
t_dmht t  INNER JOIN t_person_cid p ON t.cid=p.cid
INNER JOIN chospital h ON p.check_hosp=h.hoscode AND h.provcode IN(@prov_c)
WHERE  p.check_typearea IN(1,3) AND p.NATION IN(99) AND p.DISCHARGE IN(9)
GROUP BY p.check_hosp,p.check_vhid
);
